    /**
     * Tests getting all CreativeFiles.
     *
     * @return    Collection
     */
    public List<CreativeFile> testGetAll() throws Throwable {
    LOGGER.info( "CreativeFileTest:testGetAll() - Retrieving Collection of CreativeFiles:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CreativeFile : " );
    List<CreativeFile> collection  = null;

    try {
        // call the static get method on the CreativeFileService
        collection = service.getAllCreativeFile();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CreativeFile currEntity  = null;
            Iterator<CreativeFile> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCreativeFileId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

